contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other) public payable {
        require(other != address(0), "zero address not usable");
        require(other != address(this), "other must differ from test contract");

        uint256 reserveBefore = address(c).balance;
        uint256 callerBalBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 otherBalBefore = c.balances(other); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 callerBalAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 otherBalAfter = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 reserveAfter = address(c).balance;

        assert(
            reverted || (callerBalAfter == 0 && callerBalBefore == 0 && otherBalAfter == otherBalBefore && reserveAfter == reserveBefore)
        );
    }

    receive() external payable {}
}

